_CACHE: dict[str, Any] = {}
# rewardkit runs programmatic checks concurrently in threads; every lazy fill of _CACHE (feed generation, package
# runs, archive extraction) holds this lock so each is computed once and no check reads a half-built result.
_LOCK = threading.RLock()


def _locked(fn):
    @functools.wraps(fn)
    def inner(*args, **kwargs):
        with _LOCK:
            return fn(*args, **kwargs)
    return inner

_RUNNER = r'''
import runpy, sys
sys.path.insert(0, sys.argv[1] + "/src")
sys.argv = ["runledger"] + sys.argv[2:]
runpy.run_module("runledger", run_name="__main__")
'''


def _blob(text: str) -> Any:
    return json.loads(zlib.decompress(base64.b64decode(text)))


@_locked
def expected() -> dict:
    if "expected" not in _CACHE:
        _CACHE["expected"] = _blob(_EXPECTED_B64)
    return _CACHE["expected"]


def strict_equal(a: Any, b: Any) -> bool:
    """Equality that also requires identical JSON types (1 is not 1.0, True is not 1)."""
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(strict_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(strict_equal(x, y) for x, y in zip(a, b))
    return a == b


# ------------------------------------------------------------ stage-2 feed generator

# Stage-2 feed generator: deterministic RNG, rule parameters, value codecs, stream rendering and writers.

UTC = dt.timezone.utc
D0 = Decimal(0)


class Rng:
    """xorshift64* - stable across Python versions and platforms."""

    __slots__ = ("state",)

    def __init__(self, seed: int) -> None:
        self.state = (seed & 0xFFFFFFFFFFFFFFFF) or 0x9E3779B97F4A7C15
        for _ in range(4):
            self.next()

    def next(self) -> int:
        x = self.state
        x ^= x >> 12
        x ^= (x << 25) & 0xFFFFFFFFFFFFFFFF
        x ^= x >> 27
        self.state = x
        return (x * 0x2545F4914F6CDD1D) & 0xFFFFFFFFFFFFFFFF

    def randint(self, lo: int, hi: int) -> int:
        return lo + self.next() % (hi - lo + 1)

    def random(self) -> float:
        return (self.next() >> 11) / float(1 << 53)

    def chance(self, p: float) -> bool:
        return self.random() < p

    def choice(self, seq):
        return seq[self.next() % len(seq)]

    def shuffle(self, items: list) -> None:
        for i in range(len(items) - 1, 0, -1):
            j = self.next() % (i + 1)
            items[i], items[j] = items[j], items[i]

    def sample(self, seq, k: int) -> list:
        pool = list(seq)
        self.shuffle(pool)
        return pool[:k]

    def weighted(self, items, weights):
        total = sum(weights)
        pick = self.random() * total
        acc = 0.0
        for item, w in zip(items, weights):
            acc += w
            if pick < acc:
                return item
        return items[-1]

    def fork(self, tag: str) -> "Rng":
        h = 1469598103934665603
        for ch in tag.encode():
            h = ((h ^ ch) * 1099511628211) & 0xFFFFFFFFFFFFFFFF
        return Rng(self.next() ^ h)


def q(value, places: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_EVEN)


def iso_z(t: dt.datetime) -> str:
    return t.astimezone(UTC).strftime("%Y-%m-%dT%H:%M:%SZ")


