def make_params(seed: int) -> dict:
    rng = Rng(seed).fork("params")
    ratios = {}
    for s in SOURCE_NAMES:
        ratios[s] = {"r3": str(q(Decimal(rng.randint(9100, 11400)) / 10000, 4)),
                     "r4": str(q(Decimal(rng.randint(9600, 10700)) / 10000, 4)),
                     "r5": "1.0000"}
    epochs = {s: rng.choice(["0.8", "1.0", "1.0", "1.2", "1.5", "2.0", "3.0"]) for s in SOURCE_NAMES}
    keep_k = {s: rng.choice([1, 1, 2]) for s in SOURCE_NAMES}
    benches = []
    used = set()
    while len(benches) < 48:
        fam = rng.choice(BENCH_FAMILIES)
        name = f"{fam}-{rng.randint(10, 99)}"
        if name in used:
            continue
        used.add(name)
        benches.append(name)
    benches.sort()
    private = sorted(rng.sample(benches, 4))
    bench = {}
    for b in benches:
        bench[b] = {"weight": rng.randint(1, 5),
                    "exclude": str(q(Decimal(rng.randint(300, 450)) / 1000, 3)),
                    "taint": str(q(Decimal(rng.randint(80, 140)) / 1000, 3)),
                    "private": b in private}
    hosts = {n: f"gpu-{rng.choice(['ord', 'fra', 'bom', 'sjc'])}{rng.randint(100, 999)}" for n in NODES}
    return {
        "ratios": ratios, "epochs": epochs, "keep_k": keep_k, "bench": bench,
        "lr_peak": rng.choice(["0.0003", "0.00025", "0.0004"]),
        "lr_min_div": 10,
        "warmup": rng.randint(150, 250),
        "ramp_steps": rng.randint(350, 600),
        "tps_ramp": 1_048_576, "tps_final": 2_097_152,
        "ckpt_every": 40, "beta": "0.98", "min_select": rng.randint(550, 750),
        "n_params": rng.choice([1_288_000_000, 1_334_000_000, 1_412_000_000]),
        "gpus": {n: 8 for n in NODES},
        "hosts": hosts,
        "seeds_needed": 3,
    }


# --------------------------------------------------------------------------
# Value codecs (writer side).  Every form is documented in run_spec 3.x.
# --------------------------------------------------------------------------
_FULLWIDTH = {c: chr(ord(c) + 0xFEE0) for c in "0123456789SH"}


def key_text(kid: int) -> str:
    return f"SH{kid:07d}"


def fmt_key(kid: int, variant: str) -> str:
    canon = key_text(kid)
    if variant == "hyphen":
        return "SH-" + canon[2:]
    if variant == "lower":
        return canon.lower()
    if variant == "unpadded":
        return f"SH{kid}"
    if variant == "space":
        return f"  {canon} "
    if variant == "underscore":
        return "SH_" + canon[2:]
    if variant == "fullwidth":
        return "".join(_FULLWIDTH.get(c, c) for c in canon)
    if variant == "cyrillic":
        return "\u0405\u041d" + canon[2:]
    return canon


KEY_VARIANTS = ["hyphen", "lower", "unpadded", "space", "underscore", "fullwidth", "cyrillic"]


def fmt_int(value: int, variant: str, comma_decimal: bool) -> str:
    if variant == "thousands":
        text = f"{value:,}"
        return text.replace(",", ".") if comma_decimal else text
    if variant == "k" and value >= 1000:
        text = str(Decimal(value) / 1000)
        text = text.rstrip("0").rstrip(".") if "." in text else text
        return (text.replace(".", ",") if comma_decimal else text) + "k"
    if variant == "M" and value >= 1_000_000:
        text = str(Decimal(value) / 1_000_000)
        text = text.rstrip("0").rstrip(".") if "." in text else text
        return (text.replace(".", ",") if comma_decimal else text) + "M"
    return str(value)


def fmt_dec(value: Decimal, comma_decimal: bool, negzero: bool = False) -> str:
    text = format(value, "f")
    if negzero and value == 0:
        text = "-" + text
    return text.replace(".", ",") if comma_decimal else text


def fmt_ts(t: dt.datetime, kind: str, tz: str, variant: str = "z") -> str:
    """kind is the column kind: iso | local | epoch | epoch_ms."""
    if kind == "epoch":
        return str(int(t.timestamp()))
    if kind == "epoch_ms":
        return str(int(t.timestamp()) * 1000)
    if kind == "local":
        return t.astimezone(ZoneInfo(tz)).strftime("%Y-%m-%d %H:%M:%S")
    if variant == "offset":
        return t.astimezone(ZoneInfo(tz)).isoformat()
    return iso_z(t)


def excel_serial(t: dt.datetime, system: int) -> float:
    base = dt.datetime(1899, 12, 30, tzinfo=UTC) if system == 1900 else dt.datetime(1904, 1, 1, tzinfo=UTC)
    delta = t - base
    return delta.days + delta.seconds / 86400.0


def excel_serial_date(d: dt.date, system: int) -> int:
    base = dt.date(1899, 12, 30) if system == 1900 else dt.date(1904, 1, 1)
    return (d - base).days

# ------------------------------------------------------------ seeded world (ground truth + raw stream rows)

def _rand_ts(rng: Rng, lo: dt.datetime, hi: dt.datetime) -> dt.datetime:
    span = int((hi - lo).total_seconds())
    return lo + dt.timedelta(seconds=rng.randint(0, span))


def _hex16(rng: Rng) -> str:
    return f"{rng.next():016x}"


def _half_even_raw(rng: Rng, raw: int, ratio: str) -> int | None:
    """Nudge raw so raw*ratio lands exactly on a .5 (banker's rounding trap)."""
    r = int(Decimal(ratio) * 10000)
    for cand in range(raw, raw + 40000):
        if (cand * r) % 10000 == 5000:
            return cand
    return None


def converted(raw: int, source: str, rev: str, params: dict) -> int:
    return int((Decimal(raw) * Decimal(params["ratios"][source][rev])).quantize(Decimal(1), rounding=ROUND_HALF_EVEN))


def build_world(params: dict, stage: int, scale: float, seed: int, opening: dict) -> dict:
    rng = Rng(seed).fork(f"world-{stage}")
    cut = STAGE_CUTOVER[stage]
    lo, hi = INGEST_WINDOW[stage]
    n_shards = max(400, int(45000 * scale))
    klo, khi = KEY_RANGE[stage]
    ids = sorted(set(rng.randint(klo, khi) for _ in range(int(n_shards * 1.02))))[:n_shards]
    rng.shuffle(ids)
    weights = [9, 4, 5, 3, 3, 2, 2, 1, 3, 2, 2, 1]
    seen = list(opening.get("seen_hashes", []))
    sh: dict[int, dict] = {}
    for kid in ids:
        src = rng.weighted(SOURCE_NAMES, weights)
        rev = rng.weighted(["r3", "r4", "r5"], [3, 4, 3])
        raw = int(math.exp(13.2 + rng.random() * 1.6))
        outlier = rng.chance(0.004)
        if outlier:
            raw *= rng.randint(30, 60)
        sh[kid] = {"kid": kid, "source": src, "rev": rev, "raw": raw, "docs": max(1, raw // rng.randint(400, 3000)),
                   "ingest": _rand_ts(rng, lo, hi), "hash": _hex16(rng), "outlier": outlier,
                   "part": rng.randint(0, 8), "cluster": None, "void": False, "errata": {},
                   "recount": None, "r6": None, "license": None, "license_ok": True, "approved": True,
                   "contam": {}, "follower": False, "prior": False, "dissolved": False}
    keys = list(sh)
    # exact duplicate groups and cross-stage duplicates
    for kid in rng.sample(keys, int(len(keys) * 0.07)):
        leader = rng.choice(keys)
        if leader == kid or sh[leader]["follower"]:
            continue
        sh[kid]["hash"] = sh[leader]["hash"]
        sh[kid]["follower"] = True
        if rng.chance(0.8):
            sh[kid]["source"] = sh[leader]["source"]
    if seen:
        for kid in rng.sample(keys, int(len(keys) * 0.02)):
            if not sh[kid]["follower"]:
                sh[kid]["hash"] = rng.choice(seen)
                sh[kid]["prior"] = True
    # near-duplicate clusters (MinHash v2)
    pool = rng.sample(keys, int(len(keys) * 0.53))
    cid = 0
    clusters: dict[str, list[int]] = {}
    while pool:
        size = rng.randint(2, 6)
        members, pool = pool[:size], pool[size:]
        if len(members) < 2:
            break
        cid += 1
        name = f"MH{stage}{cid:05d}"
        clusters[name] = members
        for m in members:
            sh[m]["cluster"] = name
    dissolved = set(rng.sample(sorted(clusters), max(2, len(clusters) // 20)))
    for name in dissolved:
        for m in clusters[name]:
            sh[m]["dissolved"] = True
    # recounts (r5) and the r6 preview campaign
    recount_rows, r6_rows = [], []
    for kid in keys:
        s = sh[kid]
        if rng.chance(0.63):
            base = converted(s["raw"], s["source"], s["rev"], params)
            value = max(1, base + rng.randint(-base // 40, base // 40))
            ts = _rand_ts(rng, lo, cut)
            s["recount"] = value
            recount_rows.append({"kid": kid, "rev": "r5", "tokens": value, "status": "final", "ts": ts})
            if rng.chance(0.12):  # an older final recount superseded by the later one
                recount_rows.append({"kid": kid, "rev": "r5", "tokens": value + rng.randint(1, 900), "status": "final",
                                     "ts": ts - dt.timedelta(days=rng.randint(1, 9)), "_trap": ("T7", "4.2")})
            if rng.chance(0.08):
                recount_rows.append({"kid": kid, "rev": "r5", "tokens": value + rng.randint(-5000, 5000), "status": "provisional",
                                     "ts": ts + dt.timedelta(hours=rng.randint(1, 48)), "_trap": ("T7", "4.2")})
        if rng.chance(0.05):
            recount_rows.append({"kid": kid, "rev": "r5", "tokens": -1, "status": "failed",
                                 "ts": _rand_ts(rng, lo, cut), "_trap": ("T5", "3.6")})
        if rng.chance(0.04):
            recount_rows.append({"kid": kid, "rev": "r4", "tokens": s["raw"] + rng.randint(-999, 999), "status": "final",
                                 "ts": _rand_ts(rng, lo, cut), "_trap": ("T7", "4.2")})
        if rng.chance(0.05 if s["source"] not in R6_ADOPTED else 0.55):
            v6 = max(1, int(s["raw"] * (0.93 + rng.random() * 0.1)))
            r6_rows.append({"kid": kid, "rev": "r6", "tokens": v6, "status": "final", "ts": _rand_ts(rng, lo, cut)})
            s["r6"] = v6
    # errata (rev A in-scope; carried approvals live only in rev B)
    errata_rows, carried_rows = [], []
    eid = 0
    fields = ["tokens", "source", "license", "ingest_ts"]
    for kid in rng.sample(keys, int(len(keys) * 0.16)):
        field = rng.choice(fields)
        for _ in range(rng.randint(1, 2)):
            eid += 1
            status = rng.weighted(["APPROVED", "APPROVED_LATE", "APPROVED_EDGE", "WITHDRAWN", "PROPOSED"], [40, 14, 3, 20, 23])
            if status == "APPROVED_LATE":
                ad = (cut + dt.timedelta(days=rng.randint(1, 20))).date()
            elif status == "APPROVED_EDGE":
                ad = cut.date()
            else:
                ad = (cut - dt.timedelta(days=rng.randint(1, 40))).date()
            value = _errata_value(rng, sh[kid], field, params)
            row = {"eid": f"ER-{stage}{eid:05d}", "kid": kid, "field": field, "value": value,
                   "status": "APPROVED" if status.startswith("APPROVED") else status, "date": ad}
            if status == "APPROVED_EDGE":
                row["_trap"] = ("T11", "4.8")
            elif status in ("WITHDRAWN", "PROPOSED", "APPROVED_LATE"):
                row["_trap"] = ("T6", "4.8")
            errata_rows.append(row)
    for kid in rng.sample(keys, max(20, int(len(keys) * 0.012))):
        eid += 1
        field = rng.choice(fields)
        carried_rows.append({"eid": f"ER-{stage}{eid:05d}", "kid": kid, "field": field,
                             "value": _errata_value(rng, sh[kid], field, params), "status": "APPROVED-CARRIED",
                             "date": (cut - dt.timedelta(days=rng.randint(2, 30))).date()})
    for row in errata_rows + carried_rows:
        applies = (row["status"] in ("APPROVED", "APPROVED-CARRIED")) and row["date"] <= cut.date()
        if applies:
            cur = sh[row["kid"]]["errata"].get(row["field"])
            if cur is None or (row["date"], row["eid"]) > (cur["date"], cur["eid"]):
                sh[row["kid"]]["errata"][row["field"]] = row
    # historical errata on other stages' keys (no effect, cumulative register)
    other_lo, other_hi = KEY_RANGE[2 if stage == 1 else 1]
    hist = []
    while len(errata_rows) + len(hist) < int(15600 * scale):
        eid += 1
        hist.append({"eid": f"ER-{stage}{eid:05d}", "kid": rng.randint(other_lo, other_hi), "field": "tokens",
                     "value": str(rng.randint(10_000, 900_000)), "status": rng.choice(["APPROVED", "WITHDRAWN"]),
                     "date": (cut - dt.timedelta(days=rng.randint(40, 200))).date()})
    errata_rows += hist
    # licenses
    license_rows, revocations = [], []
    for kid in keys:
        s = sh[kid]
        grp = SOURCE_GROUP.get(s["source"], "B")
        cls = rng.weighted(["CC-BY-4.0", "MIT", "APACHE-2.0", "CC-BY-SA-4.0", "PD", "CC-BY-NC-4.0", "RESTRICTED", "N/A"],
                           [30, 10, 10, 18, 6, 4, 2, 10 if grp == "A" else 3])
        eff = cut - dt.timedelta(seconds=rng.randint(5 * 86400, 90 * 86400))
        row = {"kid": kid, "class": cls, "eff": eff}
        if cls == "N/A":
            row["_trap"] = ("T5", "3.6")
        license_rows.append(row)
        if rng.chance(0.09):
            license_rows.append({"kid": kid, "class": rng.choice(LICENSE_OK + LICENSE_BAD), "eff": eff - dt.timedelta(days=rng.randint(10, 300)),
                                 "_trap": ("T7", "4.6")})
        s["license"] = cls
    for kid in rng.sample(keys, max(10, int(len(keys) * 0.012))):
        revocations.append({"kid": kid, "reason": rng.choice(["vendor-revoked", "takedown", "contract-ended"])})
        sh[kid]["revoked"] = True
    # data cards
    card_rows = []
    doc_ids = {}
    for kid in keys:
        doc_ids[kid] = f"DC-{stage}{kid:07d}"
        nrev = rng.weighted([1, 2, 3], [82, 15, 3])
        for r in range(1, nrev + 1):
            last = r == nrev
            if last:
                status = rng.weighted(["APPROVED", "APPROVED_LATE", "APPROVED_EDGE", "DRAFT", "REJECTED"], [88, 4, 1, 4, 3])
            else:
                status = rng.choice(["APPROVED", "DRAFT", "REJECTED"])
            if status == "APPROVED_LATE":
                ad = (cut + dt.timedelta(days=rng.randint(1, 10))).date()
            elif status == "APPROVED_EDGE":
                ad = cut.date()
            elif status == "APPROVED":
                ad = (cut - dt.timedelta(days=rng.randint(1, 50))).date()
            else:
                ad = None
            row = {"kid": kid, "doc": doc_ids[kid], "revision": r, "status": "APPROVED" if status.startswith("APPROVED") else status, "date": ad}
            if status == "APPROVED_EDGE":
                row["_trap"] = ("T11", "4.7")
            elif not last:
                row["_trap"] = ("T7", "4.7")
            elif ad is None:
                row["_trap"] = ("T5", "3.6")
            card_rows.append(row)
            if last:
                sh[kid]["approved"] = row["status"] == "APPROVED" and ad is not None and ad <= cut.date()
    # contamination findings
    benches = sorted(params["bench"])
    find_rows, retracts = [], []
    fid = 0
    leaky = sorted(rng.sample(benches, 6))
    taint_holders = {b: rng.sample(keys, rng.randint(1, 4)) for b in leaky}
    def finding(kid, b, ov, trap=None):
        nonlocal fid
        fid += 1
        row = {"fid": f"F{stage}{fid:06d}", "kid": kid, "bench": b, "overlap": ov}
        if trap:
            row["_trap"] = trap
        find_rows.append(row)
        return row
    for b, holders in taint_holders.items():
        thr, taint = Decimal(params["bench"][b]["exclude"]), Decimal(params["bench"][b]["taint"])
        for kid in holders:
            finding(kid, b, q(Decimal(rng.randint(int(taint * 10000), int(thr * 10000) - 1)) / 10000, 4), ("T15", "8.4"))
    for kid in keys:
        n = rng.weighted([0, 1, 2, 3], [25, 45, 20, 10])
        for _ in range(n):
            b = rng.choice(benches)
            thr = Decimal(params["bench"][b]["exclude"])
            taint = Decimal(params["bench"][b]["taint"])
            kind = rng.weighted(["low", "high", "edge"], [93, 6, 1])
            if kind == "low":
                ov = q(Decimal(rng.randint(0, int(taint * 10000) - 1)) / 10000, 4)
            elif kind == "high":
                ov = q(Decimal(rng.randint(int(thr * 10000) + 1, 9999)) / 10000, 4)
            else:
                ov = q(thr, 4)
            row = finding(kid, b, ov, ("T11", "4.9") if kind == "edge" else None)
            if kind == "high" and rng.chance(0.18):
                retracts.append(row["fid"])
                row["retracted"] = True
        if rng.chance(0.04):
            finding(kid, rng.choice(benches), None, ("T5", "3.6"))
    rng.shuffle(find_rows)
    for row in find_rows:
        if row["overlap"] is None or row.get("retracted"):
            continue
        cur = sh[row["kid"]]["contam"].get(row["bench"])
        if cur is None or row["overlap"] > cur:
            sh[row["kid"]]["contam"][row["bench"]] = row["overlap"]
    # voids
    void_rows = []
    seq = 0
    for kid in rng.sample(keys, int(len(keys) * 0.07)):
        pattern = rng.weighted(["V", "VU", "VUV"], [55, 30, 15])
        for act in pattern:
            seq += rng.randint(1, 4)
            void_rows.append({"seq": seq, "kid": kid, "action": "VOID" if act == "V" else "UNVOID",
                              "reason": rng.choice(["ingest-error", "license-dispute", "duplicate-upload", "corrupt-object"])})
        sh[kid]["void"] = pattern[-1] == "V"
        if pattern != "V":
            void_rows[-1]["_trap"] = ("T6", "4.3")
    while len(void_rows) < int(15400 * scale):
        seq += rng.randint(1, 4)
        void_rows.append({"seq": seq, "kid": rng.randint(other_lo, other_hi), "action": rng.choice(["VOID", "UNVOID"]),
                          "reason": "historical"})
    rng.shuffle(void_rows)
    # aliases: retired keys merged into surviving keys
    alias_rows = []
    retired_of: dict[int, int] = {}
    used_ids = set(keys)
    while len(alias_rows) < int(15500 * scale):
        rid = rng.randint(9_000_000, 9_999_999)
        if rid in used_ids:
            continue
        used_ids.add(rid)
        live = rng.chance(0.35)
        surv = rng.choice(keys) if live else rng.randint(other_lo, other_hi)
        when = cut - dt.timedelta(seconds=rng.randint(10 * 86400, 400 * 86400))
        if live and rng.chance(0.06):
            alias_rows.append({"retired": rid, "surviving": rng.choice(keys), "date": when - dt.timedelta(days=rng.randint(1, 30)),
                               "_trap": ("T7", "4.4")})
        row = {"retired": rid, "surviving": surv, "date": when}
        if not live:
            row["_trap"] = ("T13", "4.4")
        alias_rows.append(row)
        if live:
            retired_of.setdefault(surv, rid)
    for kid, s in sh.items():
        if s.get("revoked"):
            s["license_ok"] = False
        else:
            cls = s["license"]
            s["license_ok"] = cls in LICENSE_OK or (cls == "N/A" and SOURCE_GROUP.get(s["source"], "B") == "A")
    world = {"stage": stage, "params": params, "opening": opening, "scale": scale, "shards": sh, "doc_ids": doc_ids,
             "streams": {"recount": recount_rows, "r6": r6_rows, "errata": errata_rows, "carried": carried_rows,
                         "license": license_rows, "revocations": revocations, "cards": card_rows,
                         "findings": find_rows, "retracts": retracts, "voids": void_rows, "aliases": alias_rows},
             "clusters": clusters, "dissolved": sorted(dissolved), "retired_of": retired_of}
    _registry_rows(world, rng)
    _inventory_rows(world, rng)
    _finalize_shards(world)
    _timeline(world, rng)
    _checkpoints_and_evals(world, rng)
    return world


def _errata_value(rng: Rng, s: dict, field: str, params: dict) -> str:
    if field == "tokens":
        return str(max(1, int(s["raw"] * (0.9 + rng.random() * 0.2))))
    if field == "source":
        return rng.choice([n for n in SOURCE_NAMES if n != s["source"]])
    if field == "license":
        return rng.choice(LICENSE_OK + LICENSE_BAD)
    return iso_z(s["ingest"] + dt.timedelta(minutes=rng.randint(-3000, 3000)))


def _registry_rows(world: dict, rng: Rng) -> None:
    sh = world["shards"]
    params = world["params"]
    alias_by_src = {}
    for old, new in SOURCE_ALIASES.items():
        alias_by_src.setdefault(new, []).append(old)
    rows, conflicts = [], []
    for kid, s in sh.items():
        src_text = s["source"]
        if s["source"] in alias_by_src and rng.chance(0.12):
            src_text = rng.choice(alias_by_src[s["source"]])
        top = rng.randint(1, 3)
        if rng.chance(0.03) and s["recount"] is None and s["r6"] is None and not s["errata"]:
            fixed = _half_even_raw(rng, s["raw"], params["ratios"][s["source"]][s["rev"]])
            if fixed is not None and s["rev"] != "r5":
                s["raw"] = fixed
                s["half_even"] = True
        home = {"kid": kid, "source": src_text, "rev": s["rev"], "raw": s["raw"], "docs": s["docs"], "ingest": s["ingest"],
                "row_rev": top, "status": "LIVE", "part": s["part"], "legacy": f"L-{(kid * 7919) % 16777216:06x}"}
        if s.get("half_even"):
            home["_trap"] = ("T12", "4.2")
        if s["outlier"]:
            home["_trap"] = ("T15", "4.2")
        rows.append(home)
        if top > 1 and rng.chance(0.3):
            rows.append(dict(home, row_rev=top - 1, raw=s["raw"] + rng.randint(1, 50000), ingest=s["ingest"] - dt.timedelta(hours=rng.randint(1, 72)),
                             _trap=("T7", "4.1")))
        if rng.chance(0.02):
            rows.append(dict(home, row_rev=top + 1, status="VOID", raw=s["raw"] * 2 + 7, _trap=("T6", "4.1")))
        if rng.chance(0.12):
            other = (s["part"] + rng.randint(1, 8)) % 9
            rows.append(dict(home, part=other, row_rev=top + rng.randint(0, 2), raw=s["raw"] + rng.randint(-90000, 90000),
                             source=rng.choice(SOURCE_NAMES), _trap=("T7", "4.1")))
            conflicts.append(kid)
    rng.shuffle(rows)
    world["streams"]["registry"] = rows
    world["routing"] = sorted(set(conflicts))


def _inventory_rows(world: dict, rng: Rng) -> None:
    sh = world["shards"]
    rows, glacier = [], []
    stage = world["stage"]
    lo, hi = INGEST_WINDOW[stage]
    for kid, s in sh.items():
        scan = _rand_ts(rng, hi, STAGE_CUTOVER[stage])
        cls = "glacier" if rng.chance(0.045) else rng.choice(["hot", "warm", "warm", "cold"])
        ref = ("key", kid)
        if kid in world["retired_of"] and rng.chance(0.25):
            ref = ("retired", world["retired_of"][kid])
        row = {"ref": ref, "kid": kid, "hash": s["hash"], "bytes": s["raw"] * rng.randint(3, 5), "scan": scan, "class": cls}
        if ref[0] == "retired":
            row["_trap"] = ("T13", "4.4")
        if cls == "glacier":
            glacier.append(row)
        else:
            rows.append(row)
        if rng.chance(0.09):
            rows.append({"ref": ("key", kid), "kid": kid, "hash": _hex16(rng), "bytes": row["bytes"], "scan": scan - dt.timedelta(days=rng.randint(1, 20)),
                         "class": "warm", "_trap": ("T7", "4.5")})
    rng.shuffle(rows)
    world["streams"]["inventory"] = rows
    world["streams"]["glacier"] = glacier


def _finalize_shards(world: dict) -> None:
    """Ground-truth shard facts exactly as the documented rules produce them."""
    params = world["params"]
    facts = {}
    for kid, s in world["shards"].items():
        if s["void"]:
            continue
        err = s["errata"]
        src = err["source"]["value"] if "source" in err else s["source"]
        if src in R6_ADOPTED and s["r6"] is not None:
            tokens = s["r6"]
        elif s["recount"] is not None:
            tokens = s["recount"]
        else:
            tokens = converted(s["raw"], src, s["rev"], params)
        if "tokens" in err:
            tokens = int(err["tokens"]["value"])
        ingest = dt.datetime.fromisoformat(err["ingest_ts"]["value"].replace("Z", "+00:00")) if "ingest_ts" in err else s["ingest"]
        lic = err["license"]["value"] if "license" in err else s["license"]
        if s.get("revoked"):
            lic_ok = False
        else:
            lic_ok = lic in LICENSE_OK or (lic == "N/A" and SOURCE_GROUP.get(src, "B") == "A")
        s["eff_source"], s["eff_tokens"], s["eff_ingest"], s["license_ok"] = src, tokens, ingest, lic_ok
        facts[key_text(kid)] = {"source": src, "tokens": tokens, "ingest_ts": iso_z(ingest), "hash": s["hash"],
                                "license_ok": lic_ok, "approved": s["approved"],
                                "cluster": None if (s["cluster"] is None or s["dissolved"]) else s["cluster"]}
    contam = {}
    for kid, s in world["shards"].items():
        if s["void"] or not s["contam"]:
            continue
        contam[key_text(kid)] = {b: str(v) for b, v in sorted(s["contam"].items())}
    world["facts"] = {"shards": dict(sorted(facts.items())), "contam": dict(sorted(contam.items()))}


def _loader_pool(world: dict) -> list[int]:
    params = world["params"]
    out = []
    for kid, s in world["shards"].items():
        if s["void"] or s["follower"] or s["prior"] or not s["approved"] or not s["license_ok"]:
            continue
        if s["cluster"] and not s["dissolved"] and world["clusters"][s["cluster"]][0] != kid:
            continue
        if any(v >= Decimal(params["bench"][b]["exclude"]) for b, v in s["contam"].items()):
            continue
        out.append(kid)
    out.sort()
    return out


def _loss_curve(step: int, rng: Rng) -> Decimal:
    base = 2.05 + 1.9 * math.exp(-step / 1400.0) + (rng.random() - 0.5) * 0.04
    return q(Decimal(repr(base)), 5)


def _timeline(world: dict, rng: Rng) -> None:
    params, stage, opening = world["params"], world["stage"], world["opening"]
    scale = world["scale"]
    pool = _loader_pool(world)
    leak_pool = sorted(k for k, s in world["shards"].items() if not s["void"] and k not in set(pool))
    void_pool = sorted(k for k, s in world["shards"].items() if s["void"])
    retired = sorted(world["retired_of"].items())
    n_att = max(300, int(9200 * scale))
    seg1 = int(n_att * 0.36)
    seg_a = opening.get("next_segment", 1)
    att0 = opening.get("next_attempt", 1)
    step0 = opening.get("optimizer_step", 0)
    t = RUN_START[stage]
    attempts = []  # dicts: seg, attempt, overflow, step (after), end
    step = step0
    seg = seg_a
    pauses = sorted(rng.sample(range(40, n_att - 40), max(3, int(14 * scale + 2))))
    pause_windows = []
    rollback = None
    for i in range(n_att):
        a = att0 + i
        if i == seg1:
            # divergence: roll back to a checkpoint well before the spike
            k = params["ckpt_every"]
            resume = ((step - 150) // k) * k
            resume = max(resume, step0 + k)
            rollback = {"from": seg, "to": seg + 1, "resume": resume, "at": t}
            gap_start = t + dt.timedelta(seconds=30)
            t += dt.timedelta(minutes=rng.randint(40, 55))
            pause_windows.append(("MAINTENANCE", None, gap_start, t))
            seg += 1
            step = resume
        if i in pauses:
            gap_start = t + dt.timedelta(seconds=30)
            t += dt.timedelta(minutes=rng.randint(18, 40))
            nodes = rng.sample(NODES, rng.randint(1, 3))
            for n in nodes:
                pause_windows.append(("PREEMPTED", n, gap_start, t))
        dur = rng.randint(85, 100)
        t += dt.timedelta(seconds=dur)
        overflow = i > 12 and rng.chance(0.06)
        if not overflow:
            step += 1
        attempts.append({"seg": seg, "attempt": a, "overflow": overflow, "step": None if overflow else step, "end": t,
                         "spike": seg == seg_a and seg1 - 120 <= i < seg1})
    world["rollback"] = rollback
    # records
    tps_of = lambda s: params["tps_ramp"] if s <= params["ramp_steps"] else params["tps_final"]
    records = []
    legacy_nodes = {"n01", "n02", "n03", "n04"}
    prev_step = step0
    for at in attempts:
        nominal = tps_of((at["step"] or prev_step + 1)) // 8
        if at["step"]:
            prev_step = at["step"]
        lpt = _loss_curve(at["step"] or prev_step, rng)
        if at["spike"]:
            lpt = q(lpt * Decimal("1.35"), 5)
        for n in NODES:
            tok = nominal - rng.randint(0, 3000)
            pick = rng.random()
            if pick < 0.010 and leak_pool:
                ref, kid = ("key", rng.choice(leak_pool)), None
                kid = ref[1]
            elif pick < 0.014 and void_pool:
                ref, kid = ("key", rng.choice(void_pool)), None
            elif pick < 0.020 and retired:
                surv, rid = rng.choice(retired)
                ref, kid = ("retired", rid), surv
            else:
                kid = rng.choice(pool)
                ref = ("key", kid)
                if at["seg"] == seg_a and n in legacy_nodes and rng.chance(0.08):
                    ref = ("legacy", f"L-{(kid * 7919) % 16777216:06x}")
            resolved = None
            if ref[0] == "retired":
                resolved = key_text(kid) if not world["shards"].get(kid, {}).get("void", True) else None
            elif ref[0] == "legacy":
                resolved = key_text(kid)
            else:
                k2 = ref[1]
                resolved = key_text(k2) if not world["shards"][k2]["void"] else None
            loss = None if at["overflow"] else q(Decimal(tok) * lpt, 3)
            records.append({"seg": at["seg"], "attempt": at["attempt"], "node": n, "ref": ref, "key": resolved,
                            "tokens": tok, "loss": loss, "ts": at["end"] + dt.timedelta(seconds=rng.randint(0, 20))})
    # replays inside preemption windows; boundary records exactly at window end
    replays = []
    by_node_attempt = {}
    for r in records:
        by_node_attempt.setdefault(r["node"], []).append(r)
    for kind, node, ws, we in pause_windows:
        if node is None:
            continue
        before = [r for r in by_node_attempt[node] if r["ts"] < ws][-12:]
        for r in before[: rng.randint(3, len(before))]:
            replays.append(dict(r, ts=ws + dt.timedelta(seconds=rng.randint(0, int((we - ws).total_seconds()) - 1)), replay=True,
                                _trap=("T6", "6.2")))
        after = [r for r in by_node_attempt[node] if r["ts"] >= we]
        if after and rng.chance(0.6):
            after[0]["ts"] = we
            after[0]["_trap"] = ("T11", "6.2")
    # node07 log truncation window (only the replay dump keeps those records)
    seg2_atts = [a for a in attempts if a["seg"] != seg_a]
    w_lo = seg2_atts[len(seg2_atts) // 3]["end"]
    w_hi = seg2_atts[len(seg2_atts) // 3 + max(20, int(300 * scale))]["end"]
    world["truncation"] = (w_lo, w_hi)
    world["attempts"] = attempts
    world["records"] = records
    world["replays"] = replays
    world["pause_windows"] = pause_windows
    # overflow alerts and retractions; calendar sessions
    world["facts"]["overflow"] = sorted([a["seg"], a["attempt"]] for a in attempts if a["overflow"])
    world["facts"]["rollbacks"] = [[rollback["from"], rollback["to"], rollback["resume"]]]
    world["facts"]["records"] = sorted([r["seg"], r["attempt"], r["node"], r["key"], r["tokens"],
                                        None if r["loss"] is None else str(r["loss"])] for r in records)
    _calendar(world, rng)


def _calendar(world: dict, rng: Rng) -> None:
    attempts = world["attempts"]
    start, end = RUN_START[world["stage"]], attempts[-1]["end"] + dt.timedelta(minutes=5)
    gaps = sorted((ws, we) for _, _, ws, we in world["pause_windows"])
    merged = []
    for ws, we in gaps:
        if merged and ws <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], we))
        else:
            merged.append((ws, we))
    events, sessions = [], []
    uid = 0
    for n in NODES:
        cursor = start
        for gs, ge in merged + [(end, end)]:
            while cursor < gs:
                nxt = min(gs, cursor + dt.timedelta(minutes=rng.randint(15, 35)))
                uid += 1
                ev = {"uid": f"sess-{world['stage']}-{uid:06d}", "node": n, "kind": "SESSION", "start": cursor, "end": nxt, "seq": 0}
                if rng.chance(0.07):
                    events.append(dict(ev, end=nxt + dt.timedelta(minutes=rng.randint(5, 40)), _trap=("T7", "9.2")))
                    ev["seq"] = 1
                events.append(ev)
                sessions.append([n, iso_z(cursor), iso_z(nxt)])
                cursor = nxt
            cursor = max(cursor, ge)
    for kind, node, ws, we in world["pause_windows"]:
        for n in ([node] if node else NODES):
            uid += 1
            events.append({"uid": f"win-{world['stage']}-{uid:06d}", "node": n, "kind": kind, "start": ws, "end": we, "seq": 0})
    for _ in range(int(len(events) * 0.05)):
        n = rng.choice(NODES)
        ws = _rand_ts(rng, start, end)
        uid += 1
        events.append({"uid": f"sess-{world['stage']}-{uid:06d}", "node": n, "kind": "SESSION", "start": ws,
                       "end": ws + dt.timedelta(minutes=30), "seq": 0, "cancelled": True, "_trap": ("T6", "9.2")})
    rng.shuffle(events)
    world["events"] = events
    world["facts"]["sessions"] = sorted(sessions)
    windows = sorted([n2, iso_z(ws), iso_z(we)] for kind, node, ws, we in world["pause_windows"] for n2 in ([node] if node else NODES))
    world["windows"] = windows


def _checkpoints_and_evals(world: dict, rng: Rng) -> None:
    params = world["params"]
    k = params["ckpt_every"]
    rb = world["rollback"]
    ckpts = []
    for at in world["attempts"]:
        if at["step"] and at["step"] % k == 0:
            ckpts.append({"id": f"ck-s{at['seg']}-{at['step']:06d}", "seg": at["seg"], "step": at["step"], "ts": at["end"]})
    resume_id = f"ck-s{rb['from']}-{rb['resume']:06d}"
    rank_rows, tomb = [], []
    facts_ck = {}
    for c in ckpts:
        incomplete = c["id"] != resume_id and rng.chance(0.05)
        missing = set(rng.sample(range(RANKS), rng.randint(1, 3))) if incomplete else set()
        partial = rng.chance(0.5) if incomplete else False
        for r in range(RANKS):
            if r in missing and not partial:
                continue
            status = "partial" if (r in missing and partial) else "ok"
            row = {"ckpt": c["id"], "seg": c["seg"], "step": c["step"], "rank": r, "status": status,
                   "bytes": params["n_params"] * 2 // RANKS + rng.randint(-4096, 4096), "ts": c["ts"] + dt.timedelta(seconds=r)}
            if r in missing:
                row["_trap"] = ("T5", "8.1")
            rank_rows.append(row)
        if rng.chance(0.04) and not incomplete and c["id"] != resume_id:
            tomb.append({"ckpt": c["id"], "reason": rng.choice(["bitrot", "checksum-mismatch", "object-lost"])})
        c["complete"] = not incomplete
        facts_ck[c["id"]] = {"segment": c["seg"], "step": c["step"], "complete": not incomplete,
                             "tombstoned": any(t["ckpt"] == c["id"] for t in tomb)}
    tomb_ids = {t["ckpt"] for t in tomb}
    for row in rank_rows:
        if "_trap" in row:
            continue
        if row["ckpt"] in tomb_ids and row["rank"] % 16 == 0:
            row["_trap"] = ("T6", "8.1")
        elif row["seg"] == rb["from"] and row["step"] > rb["resume"] and row["rank"] % 16 == 0:
            row["_trap"] = ("T13", "6.4")
    # eval_protocol E4 precedence fixtures, placed without RNG draws so the rest of the feed is unchanged: the last
    # complete abandoned checkpoint loses one rank (abandoned before incomplete), and the first checkpoint of the
    # resumed segment loses one rank and is tombstoned (incomplete before tombstoned).
    def _lose_rank(cid: str) -> None:
        row = next(r for r in rank_rows if r["ckpt"] == cid and r["rank"] == RANKS - 1)
        row["status"] = "partial"
        facts_ck[cid]["complete"] = False
        next(c for c in ckpts if c["id"] == cid)["complete"] = False
    abandoned_ck = [c for c in ckpts if c["seg"] == rb["from"] and c["step"] > rb["resume"]
                    and facts_ck[c["id"]]["complete"] and c["id"] not in tomb_ids]
    if abandoned_ck:
        _lose_rank(abandoned_ck[-1]["id"])
    resumed = next((c for c in ckpts if c["seg"] == rb["to"] and facts_ck[c["id"]]["complete"]
                    and c["id"] not in tomb_ids), None)
    if resumed is not None:
        _lose_rank(resumed["id"])
        tomb.append({"ckpt": resumed["id"], "reason": "checksum-mismatch"})
        facts_ck[resumed["id"]]["tombstoned"] = True
    world["ckpts"] = ckpts
    world["rank_rows"] = rank_rows
    world["tombstones"] = tomb
    world["facts"]["ckpts"] = dict(sorted(facts_ck.items()))
    # evaluations
    benches = sorted(params["bench"])
    base = {b: 0.25 + rng.random() * 0.35 for b in benches}
    gain = {b: 0.05 + rng.random() * 0.25 for b in benches}
    last_step = max(c["step"] for c in ckpts)
    first_step = min(c["step"] for c in ckpts)
    peak = first_step + int((last_step - first_step) * (0.55 + rng.random() * 0.25))
    eval_rows = []
    run_no = 0
    facts_ev = {}
    for c in ckpts:
        abandoned = c["seg"] == rb["from"] and c["step"] > rb["resume"]
        short = rng.chance(0.06)
        short_b = rng.choice(benches) if short else None
        for b in benches:
            mu = base[b] + gain[b] * (1 - math.exp(-c["step"] / 2500.0)) - 0.00004 * max(0, c["step"] - peak)
            mu += 0.02 * math.exp(-((c["step"] - peak) / 400.0) ** 2)
            if abandoned:
                mu += 0.05
            for seed in range(3):
                if b == short_b and seed == 2:
                    continue
                score = q(Decimal(repr(min(0.9999, max(0.0, mu + (rng.random() - 0.5) * 0.02)))), 4)
                run_no += 1
                row = {"run": f"R-{world['stage']}{run_no:06d}", "h1": f"H1-{world['stage']}{run_no:06d}", "ckpt": c["id"],
                       "bench": b, "seed": seed, "score": score, "ts": c["ts"] + dt.timedelta(minutes=rng.randint(30, 600)), "status": "ok"}
                if rng.chance(0.07):
                    run_no += 1
                    old = dict(row, run=f"R-{world['stage']}{run_no:06d}", h1=f"H1-{world['stage']}{run_no:06d}",
                               score=q(score + Decimal(rng.randint(-300, 300)) / 10000, 4).copy_abs().min(Decimal("0.9999")),
                               ts=row["ts"] - dt.timedelta(minutes=rng.randint(10, 300)),
                               status=rng.choice(["ok", "invalid"]), _trap=("T7", "8.2"))
                    eval_rows.append(old)
                if rng.chance(0.01):
                    run_no += 1
                    eval_rows.append(dict(row, run=f"R-{world['stage']}{run_no:06d}", h1=f"H1-{world['stage']}{run_no:06d}",
                                          score=Decimal("0.9999"), ts=row["ts"] + dt.timedelta(minutes=5), status="invalid",
                                          _trap=("T6", "8.2")))
                eval_rows.append(row)
                facts_ev.setdefault(c["id"], {}).setdefault(b, []).append((seed, str(score)))
    world["eval_rows"] = eval_rows
    world["facts"]["evals"] = {ck: {b: [s for _, s in sorted(v)] for b, v in sorted(bm.items())} for ck, bm in sorted(facts_ev.items())}

