class FileBuild:
    def __init__(self, name, stream, fmt, decoy, rng: Rng, stage: int):
        self.name, self.stream, self.fmt, self.decoy = name, stream, fmt, decoy
        self.rng = rng.fork(name)
        self.stage = stage
        self.sheets: list[dict] = []
        self.control: dict = {"stream": stream}
        self.extra: dict = {}
        self.traps: list[dict] = []
        self.blocks: list = []
        r = self.rng
        self.prof = {
            "tz": r.choice(["UTC", "America/Chicago", "Europe/Berlin", "Asia/Kolkata", "America/Los_Angeles"]),
            "ts_kind": r.weighted(["iso", "local", "epoch", "epoch_ms"], [5, 3, 1, 1]),
            "iso_offset": r.chance(0.35),
            "tok_k": r.chance(0.3),
            "comma": fmt == "csv" and r.chance(0.35),
            "bom": fmt in ("csv", "tsv", "txt") and r.chance(0.3),
            "crlf": False,
            "drift": fmt in DRIFT_FORMATS and r.chance(0.7),
            "unit": r.weighted(["fraction", "percent", "permille"], [5, 3, 2]),
            "date_system": r.choice([1900, 1900, 1904]),
            "serial": fmt == "xlsx" and r.chance(0.6),
            "mnats": r.chance(0.4),
        }
        if fmt in ("parquet", "sqlite", "ini", "toml", "yaml", "xlsx"):
            self.prof["ts_kind"] = r.choice(["iso", "iso", "epoch", "local"])
        self.control["tz"] = self.prof["tz"]
        if self.prof["comma"]:
            self.control["decimal"] = ","
        if decoy:
            self.control["scope"] = DECOY_SCOPE[decoy]

    @property
    def is_doc(self):
        return self.fmt in DOC_FORMATS

    def records(self) -> int:
        return sum(len(s["rows"]) for s in self.sheets)


def ts_column(base: str, kind: str) -> str:
    return {"iso": f"{base}_ts", "local": f"{base}_local", "epoch": f"{base}_epoch", "epoch_ms": f"{base}_epoch_ms",
            "serial": f"{base}_serial"}[kind]


def fmt_cell(kind: str, value, trap, fb: FileBuild):
    prof, rng = fb.prof, fb.rng
    if value is None:
        return ""
    if kind == "key":
        tag, v = value
        if tag == "legacy":
            return v
        if trap != "T1":
            return key_text(v)
        pool = KEY_VARIANTS if fb.fmt != "pdf" else ["hyphen", "lower", "unpadded", "space", "underscore"]
        return fmt_key(v, rng.choice(pool))
    if kind in ("str", "small"):
        return str(value)
    if kind == "evalue":
        field, text = value
        if trap == "T4" and field == "tokens":
            return fmt_int(int(text), "thousands", prof["comma"])
        if trap == "T3" and field == "ingest_ts":
            t = dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
            return t.astimezone(ZoneInfo(rng.choice(["Asia/Kolkata", "Europe/Berlin", "America/Chicago"]))).isoformat()
        return text
    if kind == "hash":
        return ("xxh64:" + value.upper()) if trap == "T1" else value
    if kind == "int":
        if isinstance(value, str):
            return value
        if trap == "T2":
            return fmt_int(value, "M" if value >= 1_000_000 else "k", prof["comma"])
        if trap == "T4":
            return fmt_int(value, "thousands", prof["comma"])
        return str(value)
    if kind == "int_k":
        text = format(Decimal(value) / 1000, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return text.replace(".", ",") if prof["comma"] else text
    if kind.startswith("ts_"):
        sub = kind[3:]
        if sub == "serial":
            return round(excel_serial(value, prof["date_system"]), 6)
        if sub == "iso":
            if trap == "T3":
                return value.astimezone(ZoneInfo(rng.choice(["Asia/Kolkata", "Europe/Berlin", "America/Chicago"]))).isoformat()
            return value.astimezone(ZoneInfo(prof["tz"])).isoformat() if prof["iso_offset"] else iso_z(value)
        return fmt_ts(value, sub, prof["tz"])
    if kind == "date":
        return value if isinstance(value, str) else value.isoformat()
    if kind == "date_serial":
        return value if isinstance(value, str) else excel_serial_date(value, prof["date_system"])
    if kind == "frac":
        if isinstance(value, str):
            return value
        if trap == "T2":
            return fmt_dec(q(value * 100, 2), prof["comma"]) + "%"
        unit = prof["unit"]
        scaled = value if unit == "fraction" else q(value * 100, 2) if unit == "percent" else q(value * 1000, 1)
        return fmt_dec(scaled, prof["comma"], negzero=(trap == "T4" and value == 0))
    if kind == "dec":
        return value if isinstance(value, str) else fmt_dec(value, prof["comma"])
    if kind == "notes":
        if trap == "T9":
            return rng.choice(NOTES_T9)
        if trap == "T10":
            return rng.choice(NOTES_T10)
        return rng.choice(NOTES_PLAIN)
    raise ValueError(kind)


def families_for(fb: FileBuild, columns: list) -> list[str]:
    kinds = {k for _, k, _ in columns}
    fams = []
    if "key" in kinds or "hash" in kinds:
        fams.append("T1")
    if "int" in kinds or "frac" in kinds:
        fams += ["T2", "T4"]
    if "evalue" in kinds:
        fams += ["T3", "T4"]
    if "ts_iso" in kinds and "T3" not in fams:
        fams.append("T3")
    if "notes" in kinds and fb.fmt == "csv":
        fams.append("T9")
    if "notes" in kinds and fb.fmt in ("csv", "tsv", "jsonl", "txt"):
        fams.append("T10")
    return fams or ["T1"]


def plan_traps(fb: FileBuild, n_rows: int, families: list[str], semantic: dict[int, str], formatting: bool = True,
               extra: int = 6) -> dict[int, str]:
    """Curated trap rows: one or more per 500-row band; 10-20 in-scope, >= 27 decoy."""
    r = fb.rng
    bands = max(1, math.ceil(n_rows / 500))
    per_band = 1 if not fb.decoy else 2
    picked: dict[int, str] = {}
    rot = r.randint(0, 7)
    if fb.decoy:
        for fam in ("T6", "T7", "T13", "T16", "T14", "T5"):
            rows = sorted(i for i, f in semantic.items() if f == fam)
            for i in r.sample(rows, min(3, len(rows))):
                picked[i] = fam
    for b in range(bands):
        lo, hi = b * 500, min(n_rows, (b + 1) * 500) - 1
        if hi < lo:
            continue
        sems = [i for i in semantic if lo <= i <= hi and i not in picked]
        need = per_band
        while fb.decoy and sems and need > 1:
            i = sems.pop(r.next() % len(sems))
            picked[i] = semantic[i]
            need -= 1
        if sems and (r.chance(0.5) or not formatting or fb.decoy):
            have = {}
            for v in picked.values():
                have[v] = have.get(v, 0) + 1
            i = min(sorted(sems), key=lambda j: (have.get(semantic[j], 0), r.next() & 0xFF))
            picked[i] = semantic[i]
            need -= 1
        tries = 0
        while need and tries < 50 and formatting:
            tries += 1
            i = r.randint(lo, hi)
            if i not in picked:
                picked[i] = "F:" + families[rot % len(families)]
                rot += 1
                need -= 1
    if fb.decoy and formatting:
        for fam in families:
            have = sum(1 for v in picked.values() if v == "F:" + fam)
            tries = 0
            while have < 2 and n_rows and tries < 200:
                tries += 1
                i = r.randint(0, n_rows - 1)
                if i not in picked:
                    picked[i] = "F:" + fam
                    have += 1
    goal = min(20, bands + extra) if not fb.decoy else max(27, len(picked))
    tries = 0
    pool = sorted(i for i in semantic if i not in picked)
    while len(picked) < goal and n_rows and tries < 2000:
        tries += 1
        if formatting:
            i = r.randint(0, n_rows - 1)
            if i not in picked:
                picked[i] = "F:" + families[rot % len(families)]
                rot += 1
        elif pool:
            i = pool.pop(r.next() % len(pool))
            picked[i] = semantic[i]
        else:
            break
    return picked


def emit(fb: FileBuild, sheet_name: str, columns: list, items: list, drift_ok=True, families=None, plan=True, extra=6):
    """items: list of (row, semantic_family|None).  Appends and returns the sheet."""
    fams = families or families_for(fb, columns)
    semantic = {i: f for i, (_, f) in enumerate(items) if f}
    drift = plan and fb.prof["drift"] and drift_ok and len(items) > 1000
    traps = plan_traps(fb, len(items), fams, semantic, extra=extra - (1 if drift else 0)) if plan else {}
    names = [c[0] for c in columns]
    sheet = {"name": sheet_name, "columns": names, "rows": [], "src": [], "drift_at": None, "drift_cols": None}
    if drift:
        at = fb.rng.randint(len(items) // 3, (2 * len(items)) // 3)
        alias = [ALIAS_NAMES.get(n, n) for n in names]
        order = list(range(len(names)))
        fb.rng.shuffle(order)
        sheet.update(drift_at=at, drift_cols=[alias[i] for i in order], drift_order=order)
        if at not in traps and not fb.decoy and len(traps) >= 20:
            drop = next(i for i in sorted(traps) if (i // 500) in {j // 500 for j in traps if j != i})
            del traps[drop]
        traps[at] = "F:T8"
    base = sum(len(s["rows"]) for s in fb.sheets)
    dropped: list[int] = []
    for i, (row, _sem) in enumerate(items):
        tag = traps.get(i)
        fmt_trap = tag[2:] if tag and tag.startswith("F:") else None
        cells = [fmt_cell(kind, getter(row), fmt_trap, fb) for _, kind, getter in columns]
        if fmt_trap and fmt_trap not in ("T8", "T9", "T10"):
            plain = [fmt_cell(kind, getter(row), None, fb) for _, kind, getter in columns]
            if plain == cells:
                for alt in fams:
                    if alt in ("T8", "T9", "T10"):
                        continue
                    cells = [fmt_cell(kind, getter(row), alt, fb) for _, kind, getter in columns]
                    if cells != plain:
                        tag = "F:" + alt
                        break
                else:
                    tag = None
                    dropped.append(i)
        if isinstance(row, dict) and row.get("_dagger"):
            cells[0] = f"{cells[0]}{PROVISIONAL}"
        sheet["rows"].append(cells)
        sheet["src"].append(row)
        if tag:
            fb.traps.append({"file": fb.name, "sheet": sheet_name, "row": base + i + 1,
                             "family": tag[2:] if tag.startswith("F:") else tag})
    tagged = {i for i, t in traps.items()} - set(dropped)
    bands_hit = {i // 500 for i in tagged}
    for i in dropped:
        b = i // 500
        if b in bands_hit:
            continue
        alt = [j for j in semantic if j // 500 == b and j not in tagged]
        if alt:
            j = alt[fb.rng.next() % len(alt)]
            tagged.add(j)
            bands_hit.add(b)
            fb.traps.append({"file": fb.name, "sheet": sheet_name, "row": base + j + 1, "family": semantic[j]})
    fb.sheets.append(sheet)
    return sheet


def decoy_items(fb: FileBuild, rows: list, mutate, frac=0.05):
    out = []
    for r in rows:
        if fb.rng.chance(frac):
            out.append((mutate(dict(r)), "T16"))
        else:
            out.append((dict(r), None))
    return out


def provisional(fb: FileBuild, items: list, mutate, n: int) -> list:
    """Document appendices: rows whose first cell ends with a dagger are provisional (T14)."""
    out = list(items)
    for _ in range(n):
        src = fb.rng.choice(items)[0]
        row = mutate(dict(src))
        row["_dagger"] = True
        out.insert(fb.rng.randint(0, len(out)), (row, "T14"))
    return out

# ------------------------------------------------------------ per-stream renderers (rows -> files, decoy content)

def _split(rng: Rng, items: list, n: int) -> list[list]:
    out = [[] for _ in range(n)]
    for it in items:
        out[rng.next() % n].append(it)
    return out


def _key(r):
    return ("key", r["kid"])


def _ref(r):
    tag, v = r["ref"]
    return ("legacy", v) if tag == "legacy" else ("key", v)


def _notes(_r):
    return "x"


def registry_columns(fb: FileBuild, legacy=False):
    p = fb.prof
    kind = "serial" if fb.fmt == "xlsx" and p["serial"] else p["ts_kind"]
    cols = [("shard_key", "key", _key), ("source", "str", lambda r: r["source"]), ("tokenizer_rev", "str", lambda r: r["rev"]),
            ("raw_tokens_k", "int_k", lambda r: r["raw"]) if p["tok_k"] else ("raw_tokens", "int", lambda r: r["raw"]),
            ("docs", "int", lambda r: r["docs"]), (ts_column("ingest", kind), "ts_" + kind, lambda r: r["ingest"]),
            ("row_rev", "small", lambda r: r["row_rev"]), ("row_status", "str", lambda r: r["status"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    if legacy:
        cols.append(("legacy_id", "str", lambda r: r["legacy"]))
    return cols


def inventory_columns(fb: FileBuild):
    kind = fb.prof["ts_kind"]
    cols = [("shard_key", "key", _ref), ("content_hash", "hash", lambda r: r["hash"]), ("size_bytes", "int", lambda r: r["bytes"]),
            (ts_column("scan", kind), "ts_" + kind, lambda r: r["scan"]), ("storage_class", "str", lambda r: r["class"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def license_columns(fb: FileBuild):
    kind = fb.prof["ts_kind"]
    cols = [("shard_key", "key", _key), ("license_class", "str", lambda r: r["class"]),
            (ts_column("effective", kind), "ts_" + kind, lambda r: r["eff"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def recount_columns(fb: FileBuild):
    kind = fb.prof["ts_kind"]
    cols = [("shard_key", "key", _key), ("recount_rev", "str", lambda r: r["rev"]), ("recount_tokens", "int", lambda r: r["tokens"]),
            ("recount_status", "str", lambda r: r["status"]), (ts_column("recount", kind), "ts_" + kind, lambda r: r["ts"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def finding_columns(fb: FileBuild):
    cols = [("finding_id", "str", lambda r: r["fid"]), ("shard_key", "key", _ref), ("benchmark", "str", lambda r: r["bench"]),
            ({"fraction": "overlap", "percent": "overlap_pct", "permille": "overlap_permille"}[fb.prof["unit"]], "frac",
             lambda r: "N/A" if r["overlap"] is None else r["overlap"]),
            ("scanner", "str", lambda r: r.get("scanner", "v3-8gram"))]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def neardup_columns(fb: FileBuild):
    cols = [("shard_key", "key", _key), ("cluster_id", "str", lambda r: r["cluster"]), ("similarity", "dec", lambda r: r["sim"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def errata_columns(fb: FileBuild):
    return [("errata_id", "str", lambda r: r["eid"]), ("shard_key", "key", _key), ("field", "str", lambda r: r["field"]),
            ("value", "evalue", lambda r: (r["field"], r["value"])), ("errata_status", "str", lambda r: r["status"]),
            ("approved_date", "date", lambda r: r["date"])]


def void_columns(fb: FileBuild):
    return [("action_seq", "int", lambda r: r["seq"]), ("shard_key", "key", _key), ("action", "str", lambda r: r["action"]),
            ("reason", "str", lambda r: r["reason"])]


def alias_columns(fb: FileBuild):
    kind = "iso"
    return [("retired_key", "key", lambda r: ("key", r["retired"])), ("surviving_key", "key", lambda r: ("key", r["surviving"])),
            (ts_column("merged", kind), "ts_" + kind, lambda r: r["date"])]


def trainlog_columns(fb: FileBuild, host=False):
    p = fb.prof
    kind = p["ts_kind"]
    loss = ("loss_sum_mnats", "int", lambda r: _loss_mn(r)) if p["mnats"] else ("loss_sum", "dec", lambda r: _loss_n(r))
    cols = [("segment", "small", lambda r: r["seg"]), ("attempt", "int", lambda r: r["attempt"]),
            ("host", "str", lambda r: r["host"]) if host else ("node", "str", lambda r: r["node"]),
            ("shard", "key", _ref), ("tokens", "int", lambda r: r["tokens"]), loss,
            (ts_column("ts", kind).replace("ts_ts", "ts"), "ts_" + kind, lambda r: r["ts"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def log_columns(fb: FileBuild):
    return [("segment", "small", lambda r: r["seg"]), ("attempt", "int", lambda r: r["attempt"]), ("node", "str", lambda r: r["node"]),
            ("shard", "key", _ref), ("tokens", "int", lambda r: r["tokens"]), ("loss_sum", "dec", lambda r: _loss_n(r)),
            ("ts_iso", "ts_iso", lambda r: r["ts"]), ("loss_sum_mnats", "int", lambda r: _loss_mn(r)),
            ("ts_local", "ts_local", lambda r: r["ts"])]


def _loss_n(r):
    return r.get("loss_text", "nan") if r["loss"] is None else r["loss"]


def _loss_mn(r):
    return r.get("loss_text", "nan") if r["loss"] is None else str(int(r["loss"] * 1000))


def rank_columns(fb: FileBuild):
    kind = fb.prof["ts_kind"]
    return [("ckpt_id", "str", lambda r: r["ckpt"]), ("segment", "small", lambda r: r["seg"]), ("step", "int", lambda r: r["step"]),
            ("rank", "small", lambda r: r["rank"]), ("rank_status", "str", lambda r: r["status"]),
            ("size_bytes", "int", lambda r: r["bytes"]), (ts_column("saved", kind), "ts_" + kind, lambda r: r["ts"])]


def eval_columns(fb: FileBuild, ref: str):
    kind = fb.prof["ts_kind"]
    refcol = {"run": ("run_id", "str", lambda r: r["run"]), "h1": ("h1_run_id", "str", lambda r: r["h1"]),
              "ckpt": ("ckpt_id", "str", lambda r: r["ckpt"])}[ref]
    unit = fb.prof["unit"] if fb.prof["unit"] != "permille" else "fraction"
    fb.prof["unit"] = unit
    cols = [refcol, ("benchmark", "str", lambda r: r["bench"]), ("seed", "small", lambda r: r["seed"]),
            ("score" if unit == "fraction" else "score_pct", "frac", lambda r: r.get("score_text") or r["score"]),
            (ts_column("run", kind), "ts_" + kind, lambda r: r["ts"]), ("run_status", "str", lambda r: r["status"])]
    if fb.fmt == "csv":
        cols.append(("notes", "notes", _notes))
    return cols


def _items(rows):
    return [(r, r.get("_trap", (None,))[0]) for r in rows]


# ------------------------------------------------------------------ streams

def render_stream_files(world: dict, fbs: dict[str, FileBuild], rng: Rng) -> None:
    by_stream: dict[str, list[FileBuild]] = {}
    for fb in fbs.values():
        by_stream.setdefault(fb.stream, []).append(fb)
    sh, facts = world["shards"], world["facts"]
    S = world["streams"]
    inscope = lambda st: [fb for fb in by_stream.get(st, []) if not fb.decoy]
    decoy = lambda st, d: next((fb for fb in by_stream.get(st, []) if fb.decoy == d), None)

    # registry: home partitions are the nine in-scope files in PLAN order
    reg_files = inscope("registry")
    parts = [[] for _ in reg_files]
    for r in S["registry"]:
        parts[r["part"] % len(reg_files)].append(r)
    for fb, rows in zip(reg_files, parts):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, raw=r["raw"] + 1), 12)
        emit(fb, "records", registry_columns(fb), items)
    world["home_file"] = {i: fb.name for i, fb in enumerate(reg_files)}
    fb = decoy("registry", "D01")
    if fb:
        winners = {}
        for r in S["registry"]:
            if r["status"] != "LIVE" or r["part"] != sh[r["kid"]]["part"]:
                continue
            cur = winners.get(r["kid"])
            if cur is None or r["row_rev"] > cur["row_rev"]:
                winners[r["kid"]] = r
        rows = [dict(winners[k], status="LIVE") for k in sorted(winners)]
        items = decoy_items(fb, rows, lambda r: dict(r, raw=r["raw"] + fb.rng.randint(1000, 90000), row_rev=r["row_rev"] + 1))
        for i, (r, f) in enumerate(items):
            if not f and sh[r["kid"]]["void"]:
                items[i] = (r, "T6" if fb.rng.chance(0.5) else "T13")
            elif not f and fb.rng.chance(0.004):
                items[i] = (dict(r, row_rev=r["row_rev"] + 3), "T7")
        emit(fb, "records", registry_columns(fb, legacy=True), items)

    # inventory
    inv = inscope("inventory")
    for fb, rows in zip(inv, _split(rng.fork("inv"), S["inventory"], len(inv))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, hash=f"{(int(r['hash'], 16) ^ 0xff):016x}"), 12)
        emit(fb, "records", inventory_columns(fb), items)
    fb = decoy("inventory", "D09")
    if fb:
        copies = [r for r in S["inventory"] if not r.get("_trap") or r["_trap"][0] != "T7"]
        copies = fb.rng.sample(copies, min(len(copies), max(60, int(5300 * world["scale"]) - len(S["glacier"]))))
        items = _items(S["glacier"]) + decoy_items(fb, copies, lambda r: dict(r, hash=f"{fb.rng.next():016x}"))
        voidk = [k for k, s in sh.items() if s["void"]][:40]
        items += [({"ref": ("key", k), "kid": k, "hash": sh[k]["hash"], "bytes": 10, "scan": world["opening_time"],
                    "class": "warm"}, "T6") for k in voidk[:20]]
        items += [({"ref": ("key", k), "kid": k, "hash": f"{fb.rng.next():016x}", "bytes": 10, "scan": world["opening_time"],
                    "class": "cold"}, "T7") for k in fb.rng.sample(sorted(facts_keys(world)), 15)]
        items += [({"ref": ("retired", r), "kid": k, "hash": f"{fb.rng.next():016x}", "bytes": 10,
                    "scan": world["opening_time"], "class": "cold"}, "T13") for k, r in list(world["retired_of"].items())[:15]]
        fb.rng.shuffle(items)
        emit(fb, "records", inventory_columns(fb), items)

    # licences
    lic = inscope("license")
    for r in S["license"]:
        if sh[r["kid"]]["void"] and "_trap" not in r:
            r["_trap"] = ("T6", "4.3")
    for fb, rows in zip(lic, _split(rng.fork("lic"), S["license"], len(lic))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, **{"class": "RESTRICTED"}), 12)
        if fb.name.startswith("run_spec"):
            fb.extra["appendix"] = True
        emit(fb, "records", license_columns(fb), items)
    fb = decoy("license", "D10")
    if fb:
        latest = {}
        for r in S["license"]:
            if r["kid"] not in latest or r["eff"] > latest[r["kid"]]["eff"]:
                latest[r["kid"]] = r
        copies = fb.rng.sample(sorted(latest.values(), key=lambda r: r["kid"]), min(len(latest), max(60, int(5300 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, **{"class": fb.rng.choice(LICENSE_OK + LICENSE_BAD)}))
        tag_rows(fb, items, ("T6", "T7", "T13"), sh, world)
        extra_tags(fb, items, "T5", lambda r: dict(r, **{"class": "N/A"}))
        emit(fb, "records", license_columns(fb), items)
        fb.extra["revocations"] = list(S["revocations"])
        base = fb.records()
        for j in range(0, len(S["revocations"]), 150):
            fb.traps.append({"file": fb.name, "sheet": "revocation", "row": base + j + 1, "family": "T6"})

    # data cards: two sheets per workbook, exactly balanced
    dcs = inscope("datacard")
    cards = list(S["cards"])
    by_doc = [r for r in cards if fb_doc_keyed(r, world)]
    by_key = [r for r in cards if not fb_doc_keyed(r, world)]
    per = max(1, math.ceil(max(len(by_doc), len(by_key)) / len(dcs)))
    if world["scale"] >= 1:
        per = 5000
    pad_rng = rng.fork("cardpad")

    def pad(rows, n, doc):
        rows = list(rows)
        lo, hi = KEY_RANGE[2 if world["stage"] == 1 else 1]
        while len(rows) < n:
            k = pad_rng.randint(lo, hi)
            row = {"kid": k, "doc": f"DC-9{k % 1000000:06d}", "revision": 1, "status": "APPROVED",
                   "date": dt.date(2025, 6, 1), "_hist": True}
            if len(rows) % 97 == 0:
                row["_trap"] = ("T13", "4.7")
            rows.append(row)
        return rows
    pad_rng.shuffle(by_doc)
    pad_rng.shuffle(by_key)
    a_parts = [by_key[i * per:(i + 1) * per] for i in range(len(dcs))]
    b_parts = [by_doc[i * per:(i + 1) * per] for i in range(len(dcs))]
    if world["scale"] >= 1 and (len(by_key) > per * len(dcs) or len(by_doc) > per * len(dcs)):
        raise RuntimeError("data card rows exceed sheet capacity")
    for fb, a, b in zip(dcs, a_parts, b_parts):
        a = pad(a, per, False) if world["scale"] >= 1 else a
        b = pad(b, per, True) if world["scale"] >= 1 else b
        emit(fb, "cards_by_key", card_columns(fb, by_doc=False), _items(a), extra=0)
        emit(fb, "cards_by_doc", card_columns(fb, by_doc=True), _items(b), extra=0)
    fb = decoy("datacard", "D12")
    if fb:
        latest = {}
        for r in cards:
            if r["kid"] not in latest or r["revision"] > latest[r["kid"]]["revision"]:
                latest[r["kid"]] = r
        copies = fb.rng.sample(sorted(latest.values(), key=lambda r: r["kid"]), min(len(latest), max(60, int(5000 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, status="APPROVED", date=STAGE_CUTOVER[world["stage"]].date() - dt.timedelta(days=3)))
        tag_rows(fb, items, ("T6", "T7", "T13"), sh, world)
        extra_tags(fb, items, "T5", lambda r: dict(r, date=None))
        emit(fb, "cards", card_columns(fb, by_doc=False), items)
        index_rows = sorted({(r["doc"], r["kid"]) for r in by_doc if not r.get("_hist")})
        emit(fb, "doc_index", [("doc_id", "str", lambda r: r[0]), ("shard_key", "key", lambda r: ("key", r[1]))],
             [(r, None) for r in index_rows])

    # recounts
    rc = inscope("recount")
    for fb, rows in zip(rc, _split(rng.fork("rc"), S["recount"], len(rc))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, tokens=r["tokens"] + 77, status="final"), 12)
        emit(fb, "records", recount_columns(fb), items)
    fb = decoy("recount", "D02")
    if fb:
        rows = []
        for r in S["r6"]:
            s = sh[r["kid"]]
            if s["void"]:
                rows.append((dict(r), "T6"))
                continue
            if s.get("eff_source") in R6_ADOPTED:
                rows.append((dict(r), None))
            else:
                rows.append((dict(r, tokens=s["eff_tokens"]), None))
        out = []
        for r, f in rows:
            if not f and sh[r["kid"]].get("eff_source") not in R6_ADOPTED and fb.rng.chance(0.05):
                out.append((dict(r, tokens=r["tokens"] + fb.rng.randint(5, 9000)), "T16"))
            else:
                out.append((r, f))
        tag_rows(fb, out, ("T7", "T13"), sh, world, keep=lambda r: sh[r["kid"]].get("eff_source") not in R6_ADOPTED)
        emit(fb, "records", recount_columns(fb), out)

    # contamination findings
    ct = inscope("contamination")
    finds = []
    for r in S["findings"]:
        ref = ("key", r["kid"])
        if r["kid"] in world["retired_of"] and rng.chance(0.06):
            ref = ("retired", world["retired_of"][r["kid"]])
        finds.append(dict(r, ref=ref, _trap=r.get("_trap") or (("T13", "4.9") if ref[0] == "retired" else None)))
    finds = [{k: v for k, v in f.items() if not (k == "_trap" and v is None)} for f in finds]
    for fb, rows in zip(ct, _split(rng.fork("ct"), finds, len(ct))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, overlap=Decimal("0.9000")), 12)
        emit(fb, "records", finding_columns(fb), items)
    fb = decoy("contamination", "D03")
    if fb:
        copies = fb.rng.sample(finds, min(len(finds), max(60, int(4600 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, overlap=None if r["overlap"] is None else q(r["overlap"] * Decimal("0.6"), 4),
                                                         scanner="v4-13gram"))
        for i, (r, f) in enumerate(items):
            if not f:
                items[i] = (dict(r, scanner="v4-13gram"), None)
        tag_rows(fb, items, ("T6", "T7", "T13"), sh, world)
        emit(fb, "records", finding_columns(fb), items)
        fb.extra["retracts"] = list(S["retracts"])
        base = fb.records()
        for j in range(0, len(S["retracts"]), 150):
            fb.traps.append({"file": fb.name, "sheet": "retracts", "row": base + j + 1, "family": "T6"})

    # near-duplicate clusters
    nd = inscope("neardup")
    members = []
    dissolved_set = set(world["dissolved"])
    for name, ms in world["clusters"].items():
        for m in ms:
            row = {"kid": m, "cluster": name, "sim": q(Decimal(rng.randint(8000, 9990)) / 10000, 4)}
            if name in dissolved_set:
                row["_trap"] = ("T6", "4.10")
            elif sh[m]["void"]:
                row["_trap"] = ("T13", "4.3")
            elif rng.chance(0.01):
                row["sim"] = Decimal("1.0000")
                row["_trap"] = ("T15", "4.10")
            members.append(row)
    for fb, rows in zip(nd, _split(rng.fork("nd"), members, len(nd))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, cluster="MH000000"), 12)
        emit(fb, "records", neardup_columns(fb), items)
    fb = decoy("neardup", "D13")
    if fb:
        copies = fb.rng.sample(members, min(len(members), max(60, int(5100 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, cluster=f"MH{fb.rng.randint(100000, 999999)}"))
        tag_rows(fb, items, ("T6", "T7", "T13"), sh, world)
        extra_tags(fb, items, "T15", lambda r: dict(r, sim=Decimal("1.0000")))
        emit(fb, "records", neardup_columns(fb), items)
        fb.extra["dissolved"] = list(world["dissolved"])

    # errata
    er = inscope("errata")
    for fb, rows in zip(er, _split(rng.fork("er"), S["errata"], len(er))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, status="APPROVED"), 12)
        emit(fb, "records", errata_columns(fb), items)
    fb = decoy("errata", "D07")
    if fb:
        copies = fb.rng.sample([r for r in S["errata"] if r["kid"] in sh], min(len(S["errata"]), max(40, int(4900 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, status="APPROVED" if r["status"] != "APPROVED" else "WITHDRAWN"))
        items += [(r, None) for r in S["carried"]]
        fb.rng.shuffle(items)
        tag_rows(fb, items, ("T6", "T7", "T13"), sh, world, keep=lambda r: r["status"] != "APPROVED-CARRIED")
        emit(fb, "records", errata_columns(fb), items)

    # voids and aliases
    vd = inscope("voids")
    for fb, rows in zip(vd, _split(rng.fork("vd"), S["voids"], len(vd))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, action="VOID", seq=r["seq"] + 100000), 12)
        emit(fb, "records", void_columns(fb), items)
    al = by_stream.get("aliases", [])
    for fb, rows in zip(al, _split(rng.fork("al"), S["aliases"], len(al))):
        items = _items(rows)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, surviving=r["surviving"] + 1), 12 if not fb.decoy else 30)
        if fb.decoy:
            tag_alias_decoy(fb, items, sh, world)
        emit(fb, "records", alias_columns(fb), items)

    render_trainlog(world, by_stream, rng)
    render_checkpoints(world, by_stream, rng)
    render_evals(world, by_stream, rng)


def facts_keys(world):
    return [k for k, s in world["shards"].items() if not s["void"]]


def fb_doc_keyed(r, world):
    return (r["kid"] * 2654435761) % 2 == 0


def card_columns(fb: FileBuild, by_doc: bool):
    serial = fb.fmt == "xlsx" and fb.prof["serial"]
    keycol = ("doc_id", "str", lambda r: r["doc"]) if by_doc else ("shard_key", "key", _key)
    approved = ("approved_serial", "date_serial", lambda r: r["date"] if r["date"] else "") if serial else \
        ("approved_date", "date", lambda r: r["date"] if r["date"] else ("0000-00-00" if r["revision"] % 2 else ""))
    return [keycol, ("revision", "small", lambda r: r["revision"]), ("card_status", "str", lambda r: r["status"]), approved]


def pull_mutate(fb: FileBuild, fam: str, r: dict, world: dict) -> dict:
    """Decoy pull traps: voided entity shown live (T6), stale revision (T7), FK to a superseded entity (T13)."""
    r = dict(r)
    sh = world["shards"]
    voidk = world.setdefault("_voidk", sorted(k for k, s in sh.items() if s["void"]))
    retired = world.setdefault("_retired", sorted(world["retired_of"].values()))
    ab = world.setdefault("_abandoned", [c["id"] for c in world["ckpts"] if c["seg"] == world["rollback"]["from"]
                                          and c["step"] > world["rollback"]["resume"]] or [world["ckpts"][0]["id"]])
    if fam == "T6":
        if "kid" in r and voidk:
            k = fb.rng.choice(voidk)
            r["kid"] = k
            if "ref" in r:
                r["ref"] = ("key", k)
        if "status" in r:
            r["status"] = {"invalid": "ok", "partial": "ok"}.get(r["status"], r["status"])
    elif fam == "T7":
        for f in ("eff", "date", "ts", "scan", "ingest"):
            if r.get(f):
                r[f] = r[f] - dt.timedelta(days=30)
        for f in ("revision", "row_rev"):
            if f in r:
                r[f] = max(1, r[f] - 1)
    elif fam == "T13":
        if "ckpt" in r:
            r["ckpt"] = fb.rng.choice(ab)
        elif "kid" in r and retired:
            k = fb.rng.choice(retired)
            r["kid"] = k
            if "ref" in r:
                r["ref"] = ("key", k)
    return r


def extra_tags(fb: FileBuild, items: list, fam: str, mutate, n: int = 3, keep=lambda r: True) -> None:
    """A further documented trap family inside a decoy (sentinel, boundary or valid outlier rows)."""
    cands = [i for i, (r, f) in enumerate(items) if not f and keep(r)]
    for i in fb.rng.sample(cands, min(n, len(cands))):
        items[i] = (mutate(dict(items[i][0])), fam)


def tag_rows(fb: FileBuild, items: list, fams, sh, world, keep=lambda r: True):
    """Decoys: make sure the always-required pull families are present."""
    for fam in fams:
        cands = [i for i, (r, f) in enumerate(items) if not f and keep(r)]
        for i in fb.rng.sample(cands, min(4, len(cands))):
            items[i] = (pull_mutate(fb, fam, items[i][0], world), fam)


def tag_alias_decoy(fb: FileBuild, items: list, sh, world):
    for fam in ("T6", "T7", "T13", "T16"):
        cands = [i for i, (r, f) in enumerate(items) if not f]
        for i in fb.rng.sample(cands, min(4, len(cands))):
            items[i] = (items[i][0], fam)


# ------------------------------------------------------------- training log

def render_trainlog(world: dict, by_stream: dict, rng: Rng) -> None:
    files = {fb.name: fb for fb in by_stream["trainlog"]}
    recs = world["records"] + world["replays"]
    stage = world["stage"]
    seg_a = min(a["seg"] for a in world["attempts"])
    w_lo, w_hi = world["truncation"]
    hosts = world["params"]["hosts"]
    rng2 = rng.fork("loss-sentinel")
    for r in recs:
        if r["loss"] is None and "loss_text" not in r:
            r["loss_text"] = rng2.choice(["nan", "inf", "NaN", ""])
    assign: dict[str, list] = {n: [] for n in files}
    in_window, rest = [], []
    for r in sorted(recs, key=lambda r: (r["node"], r["seg"], r["attempt"], r["ts"])):
        if r["node"] == "n07" and w_lo <= r["ts"] < w_hi and not r.get("replay"):
            in_window.append(r)
        else:
            rest.append(r)
    targets = [n for n in files if not files[n].decoy]
    chunk = math.ceil(len(rest) / len(targets))
    for i, name in enumerate(targets):
        assign[name] = sorted(rest[i * chunk:(i + 1) * chunk], key=lambda r: (r["ts"], r["attempt"], r["node"]))
    for name, rows in assign.items():
        fb = files[name]
        if fb.decoy:
            continue
        items = _items(rows)
        if name == "node_operations_handbook.docx":
            items = provisional(fb, items, lambda r: dict(r, tokens=r["tokens"] + 1), 12)
        if name == "trainlog_part11.txt":
            for r in rows:
                r["host"] = hosts[r["node"]]
            fb.control["node_field"] = "host"
            emit(fb, "records", trainlog_columns(fb, host=True), items)
        elif fb.fmt == "log":
            emit(fb, "records", log_columns(fb), items, drift_ok=False)
        else:
            emit(fb, "records", trainlog_columns(fb), items)
    fb = files.get("trainlog_part13.log")
    if fb:
        n07 = [r for r in world["records"] if r["node"] == "n07" and not (w_lo <= r["ts"] < w_hi)]
        copies = fb.rng.sample(n07, min(len(n07), max(30, int(4900 * world["scale"]))))
        items = [(r, None) for r in in_window] + decoy_items(fb, copies, lambda r: dict(r, tokens=r["tokens"] + fb.rng.randint(1, 500)))
        items.sort(key=lambda it: (it[0]["ts"], it[0]["attempt"]))
        outside = lambda r: not (w_lo <= r["ts"] < w_hi)
        tag_rows(fb, items, ("T6", "T7", "T13"), world["shards"], world, keep=outside)
        fb.control["node"] = "n07"
        emit(fb, "records", log_columns(fb), items, drift_ok=False)
    fb = files.get("trainlog_part14.tsv")
    if fb:
        copies = fb.rng.sample(world["records"], min(len(world["records"]), max(40, int(5100 * world["scale"]))))
        for r in copies:
            r.setdefault("host", hosts[r["node"]])
        items = decoy_items(fb, copies, lambda r: dict(r, tokens=r["tokens"] + fb.rng.randint(1, 500)))
        tag_rows(fb, items, ("T6", "T7", "T13"), world["shards"], world)
        emit(fb, "records", trainlog_columns(fb), items)
        emit(fb, "hosts", [("host", "str", lambda r: r[0]), ("node", "str", lambda r: r[1])],
             [((h, n), None) for n, h in sorted(hosts.items())], plan=False)


def render_checkpoints(world: dict, by_stream: dict, rng: Rng) -> None:
    files = [fb for fb in by_stream["checkpoints"] if not fb.decoy]
    rows = world["rank_rows"]
    mid = world["ckpts"][len(world["ckpts"]) // 2]["step"]
    first = [r for r in rows if (r["seg"], r["step"]) <= (world["ckpts"][len(world["ckpts"]) // 2]["seg"], mid)]
    second = [r for r in rows if r not in first] if len(rows) < 2000 else None
    if second is None:
        firstset = {id(r) for r in first}
        second = [r for r in rows if id(r) not in firstset]
    for fb, part in zip(files, [first, second]):
        items = _items(part)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, status="ok"), 12)
        emit(fb, "records", rank_columns(fb), items)
    fb = next((f for f in by_stream["checkpoints"] if f.decoy), None)
    if fb:
        lag = world["ckpts"][int(len(world["ckpts"]) * 0.9)]["ts"]
        copies = [r for r in rows if r["ts"] < lag or fb.rng.chance(0.4)]
        copies = fb.rng.sample(copies, min(len(copies), max(60, int(5200 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, status="ok" if r["status"] != "ok" else "partial"))
        tag_rows(fb, items, ("T6", "T7", "T13"), world["shards"], world)
        emit(fb, "ranks", rank_columns(fb), items)
        emit(fb, "tombstones", [("ckpt_id", "str", lambda r: r["ckpt"]), ("reason", "str", lambda r: r["reason"])],
             [(t, None) for t in world["tombstones"]], plan=False)


def render_evals(world: dict, by_stream: dict, rng: Rng) -> None:
    fbs = {fb.name: fb for fb in by_stream["evals"]}
    params = world["params"]
    private = {b for b, v in params["bench"].items() if v["private"]}
    rows = list(world["eval_rows"])
    srng = rng.fork("eval-sentinel")
    extra = []
    for r in srng.sample(rows, max(5, len(rows) // 100)):
        if r["bench"] in private:
            continue
        extra.append(dict(r, run=r["run"] + "x", h1=r["h1"] + "x", score_text="-1", ts=r["ts"] + dt.timedelta(minutes=1),
                          _trap=("T5", "3.6")))
    public = [r for r in rows + extra if r["bench"] not in private]
    priv = [r for r in rows if r["bench"] in private]
    order = ["evals_part01.csv", "evals_part02.csv", "evals_part03.json", "dashboard_evals.html", "eval_protocol.docx"]
    parts = _split(rng.fork("ev"), public, len(order))
    run_map, h1_map = [], []
    for name, part in zip(order, parts):
        fb = fbs[name]
        ref = "run" if name in ("evals_part01.csv", "evals_part02.csv") else "h1" if name == "eval_protocol.docx" else "ckpt"
        items = _items(part)
        if fb.is_doc:
            items = provisional(fb, items, lambda r: dict(r, score=Decimal("0.9990")), 12)
        emit(fb, "records", eval_columns(fb, ref), items)
        for r in part:
            if ref == "run":
                run_map.append(r)
            elif ref == "h1":
                h1_map.append(r)
    fb = fbs.get("evals_part06.xlsx")
    if fb:
        copies = fb.rng.sample(public, min(len(public), max(60, int(5000 * world["scale"]))))
        items = decoy_items(fb, copies, lambda r: dict(r, score=q(r["score"] + Decimal("0.0100"), 4)))
        tag_rows(fb, items, ("T6", "T7", "T13"), world["shards"], world)
        emit(fb, "scores", eval_columns(fb, "ckpt"), items)
        ab = {c["id"] for c in world["ckpts"] if c["seg"] == world["rollback"]["from"] and c["step"] > world["rollback"]["resume"]}
        tomb = {t["ckpt"] for t in world["tombstones"]}
        emit(fb, "run_map", [("run_id", "str", lambda r: r["run"]), ("ckpt_id", "str", lambda r: r["ckpt"])],
             [(r, "T13" if r["ckpt"] in ab else "T6" if r["status"] == "invalid" or r["ckpt"] in tomb else
               "T7" if r.get("_trap", ("",))[0] == "T7" else None) for r in sorted(run_map, key=lambda r: r["run"])],
             families=["T1"], extra=0)
    fb = fbs.get("eval_leaderboard.html")
    if fb:
        copies = fb.rng.sample(public, min(len(public), max(60, int(5300 * world["scale"]) - len(priv))))
        items = [(r, None) for r in priv] + decoy_items(fb, copies, lambda r: dict(r, score=q(r["score"] + Decimal("0.0050"), 4)))
        fb.rng.shuffle(items)
        tag_rows(fb, items, ("T6", "T7", "T13"), world["shards"], world, keep=lambda r: r["bench"] not in private)
        extra_tags(fb, items, "T5", lambda r: dict(r, score_text="-1"), keep=lambda r: r["bench"] not in private)
        emit(fb, "leaderboard", eval_columns(fb, "ckpt"), items)
    fb = fbs.get("run_spec_v3_1.docx")
    if fb:
        ab = {c["id"] for c in world["ckpts"] if c["seg"] == world["rollback"]["from"] and c["step"] > world["rollback"]["resume"]}
        edge = min((c["step"] for c in world["ckpts"] if c["step"] >= params["min_select"]), default=None)
        items = []
        for r in sorted(h1_map, key=lambda r: r["h1"]):
            fam = "T13" if r["ckpt"] in ab else "T6" if r["status"] == "invalid" else "T7" if r.get("_trap", ("",))[0] == "T7" else None
            if fam is None and edge is not None and r["ckpt"].endswith(f"-{edge:06d}"):
                fam = "T11"
            items.append((r, fam))
        items = provisional(fb, items, lambda r: dict(r, ckpt=r["ckpt"].replace("-s", "-x")), 30)
        fb.extra["t16_rows"] = True
        emit(fb, "appendix_h", [("h1_run_id", "str", lambda r: r["h1"]), ("ckpt_id", "str", lambda r: r["ckpt"])], items)

# ------------------------------------------------------------ specification documents (section numbers are the locators TRUTH.md cites)

def _tbl(fb: FileBuild, name: str, header: list[str], rows: list[list]) -> str:
    cols = [(h, "str", (lambda i: (lambda r: r[i]))(i)) for i, h in enumerate(header)]
    emit(fb, name, cols, [([str(c) for c in r], None) for r in rows], plan=False)
    return name


def doc_blocks(fb: FileBuild, world: dict) -> list:
    P, stage = world["params"], world["stage"]
    fn = DOCS.get(fb.name)
    appendix = [s["name"] for s in fb.sheets]
    blocks = fn(fb, P, stage, world) if fn else []
    for name in appendix:
        if not any(b[0] == "table" and b[1] == name for b in blocks):
            blocks += [("h", "Appendix register partition"),
                       ("p", "Rows whose first cell ends with the dagger mark are provisional entries pending review; "
                             "they are not part of the register (run_spec 3.7)."),
                       ("table", name)]
    return blocks


