def _extract_scope(fb) -> str:
    rows = [r for sh in fb.sheets if sh["name"] == "records" for r in sh["src"] if isinstance(r, dict)]
    segs = sorted({r["seg"] for r in rows})
    nodes = sorted({r["node"] for r in rows})
    return (f"segment{'s' if len(segs) > 1 else ''} {' and '.join(str(x) for x in segs)} "
            f"of node{'s' if len(nodes) > 1 else ''} {' and '.join(nodes)}")


