@criterion(description="Fires when the package code carries stage-1 answers or replays them on stage 2")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # Inverted polarity: True means the cheat happened; the negative weight does the punishing.
    def check():
        lits = source_literals()
        if not lits:
            return False
        if any(m in s for s in lits for m in expected()["markers"]):
            return True
        got = run_package("eval", eval_feed())
        if got is None or not isinstance(got.get("resume"), dict):
            return False
        # Replaying stage 1 carries its included token total into stage 2; no honest stage-2 run reproduces it.
        rc = (got.get("reconciliation") or {}).get("run_control") or {}
        return rc.get("included_tokens") == expected()["visible_rc"]["included_tokens"]
    return _safe(check)


@criterion(description="Fires when the package output changes when only the feed file names change")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # Inverted polarity: True means the output depends on file names; a package that does not run at all is
    # left to the positive checks (returns False), and run-to-run drift is left to the determinism check.
    def check():
        base = run_package("eval", eval_feed())
        again = run_package("eval-again", eval_feed())
        ren = renamed_feed()
        if base is None or again is None or ren is None or base["_bytes"] != again["_bytes"]:
            return False
        moved = run_package("eval-renamed", ren[0])
        if moved is None:
            return True
        for key in ("shard", "step", "mixture", "checkpoints", "resume"):
            if moved["_bytes"].get(key) != base["_bytes"].get(key):
                return True
        rec = json.loads(moved["_bytes"]["reconciliation"])
        for f in rec.get("chain", {}).get("files", []):
            f["name"] = ren[1].get(f["name"], f["name"])
        rec["chain"]["breaks"] = [ren[1].get(n, n) for n in rec["chain"].get("breaks", [])]
        return not strict_equal(rec, json.loads(base["_bytes"]["reconciliation"]))
    return _safe(check)


@criterion(description="Fires when the package code carries a path under the shipped corpus root as a literal")
def negative_corpus_path_literal_in_package(workspace: Path) -> bool:
    # Inverted polarity: True means code under src/ carries the corpus path; comments, docstrings and the
    # project's tests are not scanned, so mentioning the path in prose costs nothing.
    # Only a literal that IS a path under the corpus root counts (a default, an open() argument, an f-string
    # prefix); prose that merely mentions the path, such as a help text example, does not.
    corpus_root = str(Path("/app") / "data")
    return _safe(lambda: any(s.strip() == corpus_root or s.strip().startswith(corpus_root + "/")
                             for s in source_literals()))


@criterion(description="Fires when two runs of the package on the same feed differ")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Inverted polarity: True means two runs on the same feed produced different bytes.
    def check():
        a = run_package("eval", eval_feed())
        b = run_package("eval-again", eval_feed())
        return a is not None and b is not None and a["_bytes"] != b["_bytes"]
    return _safe(check)


